INSERT INTO article (langCode, title, wikiCategory, idBase) VALUES ('en', 'Piracy', 'GAME_MECHANICS', null);
INSERT INTO articleRevision (version, idArticle, idAuthor) VALUES (1, LAST_INSERT_ID(), 1);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '# Piracy', 'INSERT', 0);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '---', 'INSERT', 1);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '### A dangerous galaxy', 'INSERT', 2);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 3);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'There are countless reasons for illegal activities and the space inhabited by humans is not necessarily safe.  ', 'INSERT', 4);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'In spacefare, pirates are a common threat and nearly everywhere.', 'INSERT', 5);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 6);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'Countless **officially uninhabited places** are hideouts for any kind of groups outside the civilized society.', 'INSERT', 7);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 8);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '---', 'INSERT', 9);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 10);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '#### Occurrence', 'INSERT', 11);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 12);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'Nearly every place will be visited by pirates as long as there are reasons for piracy.  ', 'INSERT', 13);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'The question unfortunately isn\'t how to redeem piracy, it it how to avoid and survive it.', 'INSERT', 14);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 15);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'To protect your commercial and private shipping, it is advisable to set up police forces.', 'INSERT', 16);
INSERT INTO article_articleRevisions (Article_idArticle, articleRevisions_idArticleRevision) VALUES ((SELECT MAX(idArticle) from article), (SELECT MAX(idArticleRevision) from articleRevision));
INSERT INTO article (langCode, title, wikiCategory, idBase) VALUES ('en', 'Pirate hunt', 'MISSION_TYPES', null);
INSERT INTO articleRevision (version, idArticle, idAuthor) VALUES (1, LAST_INSERT_ID(), 1);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '# Pirate hunt', 'INSERT', 0);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '---', 'INSERT', 1);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '### Goal', 'INSERT', 2);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 3);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'The **pirate hunt** will staff police forces in order to secure the space around the mission areas.  ', 'INSERT', 4);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'The forces sent will patrol the area and protect trade routes.', 'INSERT', 5);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 6);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '#### Deployment of naval forces', 'INSERT', 7);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 8);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'Warships can be detached from fleets or a full fleet or flotilla can be taken to fulfil police missions.  ', 'INSERT', 9);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'The operation area must be defined and the forces will reduce the trade jamming activities in the area.', 'INSERT', 10);
INSERT INTO article_articleRevisions (Article_idArticle, articleRevisions_idArticleRevision) VALUES ((SELECT MAX(idArticle) from article), (SELECT MAX(idArticleRevision) from articleRevision));
INSERT INTO article (langCode, title, wikiCategory, idBase) VALUES ('en', 'Convoy protection', 'MISSION_TYPES', null);
INSERT INTO articleRevision (version, idArticle, idAuthor) VALUES (1, LAST_INSERT_ID(), 1);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '# Convoy protection', 'INSERT', 0);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '---', 'INSERT', 1);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '### Goal', 'INSERT', 2);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 3);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '**Convoy protection** will send fleets or flotillas along with trading or passenger ships to protect them on their ride from pirates.', 'INSERT', 4);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 5);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '#### Deployment of naval forces', 'INSERT', 6);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 7);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'The designated ships will automatically pick up convoys and protect them.  ', 'INSERT', 8);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), 'If there are more convoys then available ships, the left over convoys will be travelling unprotected.', 'INSERT', 9);
INSERT INTO articleLines (idArticleRevision, content, deltaType, lineNo) VALUES (LAST_INSERT_ID(), '', 'INSERT', 10);
